const ZERO_ADDRESS: Address = "0x0000000000000000000000000000000000000000";
const isDeployed = (a: Address | undefined | null): boolean => !!a && a !== ZERO_ADDRESS;

// ── Stock-reward domain constants (mirror the app's src/lib/stock-launch.ts) ──────────────────

/** Target opening market cap (USD) the stock pool is seeded at — $5,500 on a 1B supply. */
export const STOCK_TARGET_MCAP_USD = 5500n;

/** Tax bounds — enforced ON-CHAIN by the token/hook (MIN_TAX_BPS / MAX_TAX_BPS). */
export const MIN_TAX_BPS = 200; // 2%
export const MAX_TAX_BPS = 500; // 5%
export const DEFAULT_TAX_BPS = 400; // 4% — the suggested opening value

/** Fixed cuts (of VOLUME) — flat regardless of tax; holders get the remainder (tax − 1.0%). */
export const CREATOR_FEE_BPS = 50; // 0.5% → token creator
export const FLYWHEEL_BPS = 10; // 0.1% → flywheel (buy+burn)
export const PLATFORM_NET_BPS = 40; // 0.4% → platform treasury
export const FIXED_CUT_BPS = CREATOR_FEE_BPS + FLYWHEEL_BPS + PLATFORM_NET_BPS; // 100

/** A basket's weightBps entries MUST total this (100.00%). */
export const WEIGHT_TOTAL_BPS = 10000;

/** Default v4 pool tier the stock launcher opens at — the 1% memecoin tier (tickSpacing 200). */
export const STOCK_V4_FEE_TIER = 10000;
export const STOCK_V4_TICK_SPACING = 200;
/** Default sniper-guard window armed by the launch (seconds; capped ≤ 1h on-chain). */
export const STOCK_V4_GUARD_WINDOW_SECS = 180n;

/** Selectable reward universe (only stocks with a KNOWN token address; mirrors rh-stocks.ts). */
export const STOCK_UNIVERSE: StockRef[] = [
  { symbol: "NVDA", name: "NVIDIA", token: "0xd0601CE157Db5bdC3162BbaC2a2C8aF5320D9EEC", feed: "0x379EC4f7C378F34a1B47E4F3cbeBCbAC3E8E9F15", liquidity: true },
  { symbol: "AAPL", name: "Apple", token: "0xaF3D76f1834A1d425780943C99Ea8A608f8a93f9", feed: "0x6B22A786bAa607d76728168703a39Ea9C99f2cD0", liquidity: false },
  { symbol: "TSLA", name: "Tesla", token: "0x322F0929c4625eD5bAd873c95208D54E1c003b2d", feed: "0x4A1166a659A55625345e9515b32adECea5547C38", liquidity: false },
];

/** The default single-stock reward — the only stock with live on-chain liquidity today. */
export const DEFAULT_REWARD_SYMBOL = "NVDA";

export function stockBySymbol(symbol: string): StockRef | undefined {
  return STOCK_UNIVERSE.find((s) => s.symbol.toUpperCase() === symbol.toUpperCase());
}

/** Split one side's tax (bps of volume) into the fixed creator/flywheel/platform cuts + holders. */
export function splitForTax(taxBps: number): FeeSplitPreview {
  const clamped = Math.max(MIN_TAX_BPS, Math.min(MAX_TAX_BPS, Math.round(taxBps)));
  return {
    taxBps: clamped,
    creatorBps: CREATOR_FEE_BPS,
    flywheelBps: FLYWHEEL_BPS,
    platformBps: PLATFORM_NET_BPS,
    holdersBps: Math.max(0, clamped - FIXED_CUT_BPS),
  };
}

/** Equal-weight the picked symbols (index mode). Distributes the rounding remainder to the first. */
export function equalWeights(symbols: string[]): { symbol: string; weightPct: number }[] {
  const n = symbols.length;
  if (n === 0) return [];
  const base = Math.floor(100 / n);
  const rem = 100 - base * n;
  return symbols.map((symbol, i) => ({ symbol, weightPct: base + (i < rem ? 1 : 0) }));
}

/** Convert a UI draft (whole percent) to on-chain basket entries (bps). Weights MUST sum to 100
 *  (→ 10000 bps) or the vault's setBasket reverts BadWeights. Unknown symbols are dropped. */
export function draftToBasketEntries(draft: { symbol: string; weightPct: number }[]): StockBasketEntry[] {
  return draft
    .map((d) => {
      const ref = stockBySymbol(d.symbol);
      if (!ref) return null;
      return { stock: ref.token, weightBps: Math.round(d.weightPct * 100) };
    })
    .filter((e): e is StockBasketEntry => e !== null);
}

/**
 * Map launch inputs → the exact `StockRewardLauncherV4.LaunchParams` tuple. The single-sided seed
 * geometry (sqrtPriceX96 / ticks) is computed off-chain for the PREDICTED TOKEN/WETH sort by
 * `computeV3FairLaunchParams`. The WETH→TOKEN dev buy limits at MAX when the token is currency0
 * (price-up buy) and MIN otherwise — the real slippage floor is `initialBuyMinOut`.
 */
export function buildStockLaunchParamsV4(args: {
  name: string;
  symbol: string;
  supply: bigint; // full 18-dec supply (wei)
  admin: Address;
  creator: Address;
  buyBps: number;
  sellBps: number;
  sqrtPriceX96: bigint;
  tickLower: number;
  tickUpper: number;
  tokenIsZero: boolean;
  fee?: number;
  tickSpacing?: number;
  creatorAmount?: bigint;
  guardWindowSecs?: bigint;
  initialBuyEth?: bigint;
  initialBuyMinOut?: bigint;
}): StockLaunchParamsV4 {
  const initialBuyEth = args.initialBuyEth ?? 0n;
  const initialBuyMinOut = args.initialBuyMinOut ?? 0n;
  const initialBuyLimitSqrtPriceX96 = args.tokenIsZero ? V3_MAX_SQRT_RATIO : V3_MIN_SQRT_RATIO;
  return {
    name: args.name,
    symbol: args.symbol,
    supply: args.supply,
    creatorAmount: args.creatorAmount ?? 0n, // pure fair launch by default
    sqrtPriceX96: args.sqrtPriceX96,
    tickLower: args.tickLower,
    tickUpper: args.tickUpper,
    fee: args.fee ?? STOCK_V4_FEE_TIER,
    tickSpacing: args.tickSpacing ?? STOCK_V4_TICK_SPACING,
    admin: args.admin,
    creator: args.creator,
    buyBps: args.buyBps,
    sellBps: args.sellBps,
    guardWindowSecs: args.guardWindowSecs ?? STOCK_V4_GUARD_WINDOW_SECS,
    initialBuyEth,
    initialBuyMinOut,
    initialBuyLimitSqrtPriceX96,
  };
}

interface BuiltStockLaunch {
  params: StockLaunchParamsV4;
  predictedToken: Address;
  tokenIsZero: boolean;
}

/**
 * StockRewardModule — the stock-reward launch mechanic (Robinhood Chain 4663 only).
 *
 * A stock-reward token is a fair, direct-to-DEX launch (no bonding curve) with a 2–5% buy/sell tax
 * whose proceeds buy REAL tokenized stocks (NVDA / AAPL / a basket / an index) and drip them to
 * holders every epoch via a Merkle distributor. The preferred venue is StockRewardLauncherV4 — a
 * clean, untaxed token into a Uniswap-v4 TOKEN/WETH pool with StockTaxHook charging the tax in WETH
 * (so sells are never honeypotted). The legacy StockRewardLauncherV2 (token-taxed direct-to-v3)
 * remains available.
 *
 * This is Robinhood-only: every method throws a clear error on chains where the suite isn't
 * deployed. Instantiate the client with `chainId: 4663`.
 *
 * @example
 * ```ts
 * const hookos = new HookOS({ chainId: 4663, walletClient });
 *
 * // Reads
 * const universe = hookos.stock.getRewardUniverse();          // NVDA / AAPL / TSLA
 * const split = hookos.stock.previewFeeSplit(400);            // 4% tax → holdersBps 300
 * const allowed = await hookos.stock.isStockAllowed(nvda);
 *
 * // Launch (V4 by default — ticks/sqrtPrice computed for you)
 * const res = await hookos.stock.launch({
 *   name: "Nvidia Rewards", symbol: "NVDAR", supplyTokens: 1_000_000_000n, buyBps: 400, sellBps: 400,
 * });
 *
 * // Claim (proof supplied by the keeper/indexer)
 * await hookos.stock.claim({ epoch: 3n, stock: nvda, amount, proof });
 * ```
 */
export class StockRewardModule {
  constructor(
    private readonly addresses: StockRewardAddresses | null,
    private readonly chainId: number,
    private readonly publicClient: PublicClient,
    private readonly walletClient?: WalletClient,
  ) {}

  /** Whether the stock-reward suite is deployed on the client's chain. */
  get available(): boolean {
    return (!!this.addresses && isDeployed(this.addresses.launcherV4)) || (!!this.addresses && isDeployed(this.addresses.launcherV2));
  }

  private requireDeployed(op: string): StockRewardAddresses {
    if (!this.addresses) {
      throw new ContractCallError(
        "StockRewardLauncher",
        op,
        `stock-reward launches are Robinhood-only (chain 4663) — not deployed on chain ${this.chainId}`,
      );
    }
    return this.addresses;
  }

  private requireWallet(op: string) {
    if (!this.walletClient) throw new WalletRequiredError(op);
    const account = this.walletClient.account;
    if (!account) throw new WalletRequiredError(`${op} (no account)`);
    return account;
  }

  // ── Static reward data ────────────────────────────────────────────────────

  /** The selectable reward universe (tokenized stocks + Chainlink feeds). */
  getRewardUniverse(): StockRef[] {
    return STOCK_UNIVERSE;
  }

  /** Look up a reward stock by symbol (case-insensitive). */
  stockBySymbol(symbol: string): StockRef | undefined {
    return stockBySymbol(symbol);
  }

  /** Preview how a per-side tax (bps) splits between creator/flywheel/platform + holders. */
  previewFeeSplit(taxBps: number): FeeSplitPreview {
    return splitForTax(taxBps);
  }

  // ── Reads: vault ──────────────────────────────────────────────────────────

  /** The creator's chosen reward basket for a token (weights in bps, summing to 10000). */
  async getBasket(rewardToken: Address): Promise<StockBasketEntry[]> {
    const a = this.requireDeployed("getBasket");
    const res = (await this.publicClient.readContract({
      address: a.vault,
      abi: StockRewardVaultABI,
      functionName: "getBasket",
      args: [rewardToken],
    })) as readonly { stock: Address; weightBps: number }[];
    return res.map((e) => ({ stock: e.stock, weightBps: Number(e.weightBps) }));
  }

  /** Whether a stock is on the vault's reward allowlist. */
  async isStockAllowed(stock: Address): Promise<boolean> {
    const a = this.requireDeployed("stockAllowed");
    return this.publicClient.readContract({
      address: a.vault,
      abi: StockRewardVaultABI,
      functionName: "stockAllowed",
      args: [stock],
    });
  }

  /** The Chainlink USD feed (8dp) the vault has bound to a stock. */
  async getStockPriceFeed(stock: Address): Promise<Address> {
    const a = this.requireDeployed("priceFeed");
    return this.publicClient.readContract({
      address: a.vault,
      abi: StockRewardVaultABI,
      functionName: "priceFeed",
      args: [stock],
    });
  }

  /** The undistributed holder USDG pool accrued for a reward token. */
  async getHolderPool(rewardToken: Address): Promise<bigint> {
    const a = this.requireDeployed("holderUsdgPool");
    return this.publicClient.readContract({
      address: a.vault,
      abi: StockRewardVaultABI,
      functionName: "holderUsdgPool",
      args: [rewardToken],
    });
  }

  /** Total holder USDG the vault is currently holding across all tokens. */
  async getTotalHolderUsdg(): Promise<bigint> {
    const a = this.requireDeployed("totalHolderUsdg");
    return this.publicClient.readContract({
      address: a.vault,
      abi: StockRewardVaultABI,
      functionName: "totalHolderUsdg",
    });
  }

  /** Total of a given stock the vault has bought for holders so far. */
  async getTotalStockBought(stock: Address): Promise<bigint> {
    const a = this.requireDeployed("totalStockBought");
    return this.publicClient.readContract({
      address: a.vault,
      abi: StockRewardVaultABI,
      functionName: "totalStockBought",
      args: [stock],
    });
  }

  /**
   * The live WETH/USD price floor the vault prices stock buys against, read from the
   * WethUsdAggregatorAdapter (a Chainlink-shaped feed wrapping the keeper price). `answer` is
   * `decimals`-scaled (8dp). Returns zeros when the underlying keeper price is stale/bad
   * (the adapter fails CLOSED).
   */
  async getWethUsdPrice(): Promise<{ answer: bigint; decimals: number; updatedAt: number }> {
    const a = this.requireDeployed("wethUsd");
    const [round, decimals] = await Promise.all([
      this.publicClient.readContract({
        address: a.wethUsdAdapter,
        abi: WethUsdAggregatorABI,
        functionName: "latestRoundData",
      }) as Promise<readonly [bigint, bigint, bigint, bigint, bigint]>,
      this.publicClient.readContract({
        address: a.wethUsdAdapter,
        abi: WethUsdAggregatorABI,
        functionName: "decimals",
      }) as Promise<number>,
    ]);
    return { answer: round[1], decimals: Number(decimals), updatedAt: Number(round[3]) };
  }

  // ── Reads: launcher ───────────────────────────────────────────────────────

  /** Whether `token` was launched via the V4 stock-reward launcher. */
  async isStockRewardToken(token: Address): Promise<boolean> {
    const a = this.requireDeployed("isStockRewardToken");
    return this.publicClient.readContract({
      address: a.launcherV4,
      abi: StockRewardLauncherV4ABI,
      functionName: "isStockRewardToken",
      args: [token],
    });
  }

  /** Total number of V4 stock-reward launches to date. */
  async getLaunchCount(): Promise<bigint> {
    const a = this.requireDeployed("launchCount");
    return this.publicClient.readContract({
      address: a.launcherV4,
      abi: StockRewardLauncherV4ABI,
      functionName: "launchCount",
    });
  }

  // ── Launch (build + write) ────────────────────────────────────────────────

  /**
   * Compute the full `StockRewardLauncherV4.LaunchParams` tuple (weth read + token prediction +
   * live keeper price + ticks/sqrtPrice) WITHOUT sending. Useful for previewing or custom flows.
   */
  async buildLaunchParamsV4(opts: StockLaunchOptions): Promise<BuiltStockLaunch> {
    const a = this.requireDeployed("buildLaunchParamsV4");
    if (!isDeployed(a.launcherV4)) {
      throw new ContractCallError("StockRewardLauncherV4", "launch", "V4 launcher not deployed — use the V2 path");
    }
    const account = this.walletClient?.account?.address;
    const creator = opts.creator ?? account;
    if (!creator) throw new ValidationError("creator", "provide `creator` or a wallet client");
    const admin = opts.admin ?? creator;
    const buyBps = opts.buyBps ?? DEFAULT_TAX_BPS;
    const sellBps = opts.sellBps ?? DEFAULT_TAX_BPS;
    if (buyBps < MIN_TAX_BPS || buyBps > MAX_TAX_BPS || sellBps < MIN_TAX_BPS || sellBps > MAX_TAX_BPS) {
      throw new ValidationError("taxBps", `buy/sell tax must be within [${MIN_TAX_BPS}, ${MAX_TAX_BPS}] bps`);
    }
    const targetMcapUsd = opts.targetMcapUsd ?? STOCK_TARGET_MCAP_USD;
    const supplyTokens = opts.supplyTokens;
    const supplyWei = supplyTokens * 10n ** 18n;

    const launcher = a.launcherV4;
    const weth = (await this.publicClient.readContract({
      address: launcher,
      abi: StockRewardLauncherV4ABI,
      functionName: "weth",
    })) as Address;

    // Token is deployed via plain CREATE → address == CREATE(launcher, launcher-nonce).
    const nonce = await this.publicClient.getTransactionCount({ address: launcher });
    const predictedToken = getContractAddress({ from: launcher, nonce: BigInt(nonce) });
    const tokenIsZero = predictedToken.toLowerCase() < weth.toLowerCase();

    const { nativeUsdPrice } = await this.readKeeperPrice(a.bondingCurve);

    const fp = computeV3FairLaunchParams({
      targetMcapUsd,
      supplyTokens,
      nativeUsdPrice,
      tokenIsZero,
      feeTier: V3_DEFAULT_FEE_TIER,
    });
    if (fp.tickLower % STOCK_V4_TICK_SPACING !== 0 || fp.tickUpper % STOCK_V4_TICK_SPACING !== 0 || fp.tickLower >= fp.tickUpper) {
      throw new ValidationError("ticks", "computed tick range is invalid for this DEX — try again");
    }

    let initialBuyEth = 0n;
    let initialBuyMinOut = 0n;
    if (opts.devBuyEth && opts.devBuyEth > 0) {
      initialBuyEth = parseEther(opts.devBuyEth.toString());
      const nativeUsdFloat = Number(nativeUsdPrice) / 1e18;
      const supplyNum = Number(supplyTokens);
      const seedPriceNative = nativeUsdFloat > 0 && supplyNum > 0
        ? Number(targetMcapUsd) / supplyNum / nativeUsdFloat
        : 0;
      if (seedPriceNative > 0) {
        const expectedTokens = Number(formatEther(initialBuyEth)) / seedPriceNative;
        const floorTokens = expectedTokens * 0.5; // 50% floor absorbs pool fee + impact + buy tax
        if (Number.isFinite(floorTokens) && floorTokens > 0) initialBuyMinOut = parseEther(floorTokens.toFixed(18));
      }
      if (initialBuyMinOut <= 0n) throw new ValidationError("devBuyEth", "could not derive a safe minimum for the dev buy");
    }

    const params = buildStockLaunchParamsV4({
      name: opts.name,
      symbol: opts.symbol.toUpperCase(),
      supply: supplyWei,
      admin,
      creator,
      buyBps,
      sellBps,
      sqrtPriceX96: fp.sqrtPriceX96,
      tickLower: fp.tickLower,
      tickUpper: fp.tickUpper,
      tokenIsZero,
      guardWindowSecs: opts.guardWindowSecs,
      initialBuyEth,
      initialBuyMinOut,
    });

    return { params, predictedToken, tokenIsZero };
  }

  /**
   * Launch a stock-reward token. Defaults to the V4 (WETH-paired, hook-taxed) launcher; pass
   * `useV2: true` (or launch on a chain where only V2 is deployed) for the legacy v3 path.
   * Requires a wallet client. Returns the launched token + poolId (decoded from `Launched`).
   */
  async launch(opts: StockLaunchOptions): Promise<StockLaunchResult> {
    const a = this.requireDeployed("launch");
    const account = this.requireWallet("stock.launch");
    const useV4 = !opts.useV2 && isDeployed(a.launcherV4);
    if (useV4) {
      const { params } = await this.buildLaunchParamsV4(opts);
      return this.launchV4(params, params.initialBuyEth);
    }
    // Legacy V2 path.
    if (!isDeployed(a.launcherV2)) {
      throw new ContractCallError("StockRewardLauncherV2", "launch", "legacy V2 launcher not deployed on this chain");
    }
    const creator = opts.creator ?? account.address;
    const admin = opts.admin ?? creator;
    const buyBps = opts.buyBps ?? DEFAULT_TAX_BPS;
    const sellBps = opts.sellBps ?? DEFAULT_TAX_BPS;
    const targetMcapUsd = opts.targetMcapUsd ?? STOCK_TARGET_MCAP_USD;
    const supplyWei = opts.supplyTokens * 10n ** 18n;

    const weth = (await this.publicClient.readContract({
      address: a.launcherV2,
      abi: StockRewardLauncherV2ABI,
      functionName: "weth",
    })) as Address;
    const nonce = await this.publicClient.getTransactionCount({ address: a.launcherV2 });
    const predictedToken = getContractAddress({ from: a.launcherV2, nonce: BigInt(nonce) });
    const tokenIsZero = predictedToken.toLowerCase() < weth.toLowerCase();
    const { nativeUsdPrice } = await this.readKeeperPrice(a.bondingCurve);
    const fp = computeV3FairLaunchParams({ targetMcapUsd, supplyTokens: opts.supplyTokens, nativeUsdPrice, tokenIsZero, feeTier: V3_DEFAULT_FEE_TIER });

    const params: StockLaunchParamsV2 = {
      name: opts.name,
      symbol: opts.symbol.toUpperCase(),
      supply: supplyWei,
      creatorAmount: 0n,
      tickLower: fp.tickLower,
      tickUpper: fp.tickUpper,
      admin,
      creator,
      vault: a.vault,
      buyBps,
      sellBps,
      dex: opts.dex ?? 0,
      initialBuyEth: 0n,
      initialBuyMinOut: 0n,
      initialBuyDeadline: 0n,
    };
    return this.launchV2(params, predictedToken);
  }

  /** Send a prebuilt V4 launch tuple. `value` funds the atomic dev buy (defaults to initialBuyEth). */
  async launchV4(params: StockLaunchParamsV4, value?: bigint): Promise<StockLaunchResult> {
    const a = this.requireDeployed("launchV4");
    const account = this.requireWallet("stock.launchV4");
    const hash = await this.walletClient!.writeContract({
      address: a.launcherV4,
      abi: StockRewardLauncherV4ABI,
      functionName: "launch",
      args: [params],
      value: value ?? params.initialBuyEth,
      account,
      chain: this.walletClient!.chain,
    });
    const receipt = await this.publicClient.waitForTransactionReceipt({ hash });
    if (receipt.status === "reverted") throw new ContractCallError("StockRewardLauncherV4", "launch", "reverted on-chain");

    let token: Address = ZERO_ADDRESS;
    let pool: Hash = ("0x" + "0".repeat(64)) as Hash;
    let seededToPool = 0n;
    let toCreator = 0n;
    for (const log of receipt.logs) {
      try {
        const decoded = decodeEventLog({ abi: StockRewardLauncherV4ABI, data: log.data, topics: log.topics });
        if (decoded.eventName === "Launched") {
          const args = decoded.args as { token: Address; poolId: Hash; seededToPool: bigint; toCreator: bigint };
          token = args.token;
          pool = args.poolId;
          seededToPool = args.seededToPool;
          toCreator = args.toCreator;
          break;
        }
      } catch { /* not our event */ }
    }
    if (token === ZERO_ADDRESS) throw new ContractCallError("StockRewardLauncherV4", "launch", "Launched event not found in receipt");

    // Fetch the position id (not carried in the event) — best-effort.
    let positionId: bigint | undefined;
    try {
      const info = (await this.publicClient.readContract({
        address: a.launcherV4,
        abi: StockRewardLauncherV4ABI,
        functionName: "getLaunchByToken",
        args: [token],
      })) as { positionId: bigint };
      positionId = info.positionId;
    } catch { /* optional */ }

    return { token, pool, positionId, seededToPool, toCreator, txResult: this.toTx(receipt) };
  }

  /** Send a prebuilt legacy V2 launch tuple. `predictedToken` is a receipt-decode fallback. */
  async launchV2(params: StockLaunchParamsV2, predictedToken?: Address): Promise<StockLaunchResult> {
    const a = this.requireDeployed("launchV2");
    const account = this.requireWallet("stock.launchV2");
    const hash = await this.walletClient!.writeContract({
      address: a.launcherV2,
      abi: StockRewardLauncherV2ABI,
      functionName: "launch",
      args: [params],
      value: params.initialBuyEth,
      account,
      chain: this.walletClient!.chain,
    });
    const receipt = await this.publicClient.waitForTransactionReceipt({ hash });
    if (receipt.status === "reverted") throw new ContractCallError("StockRewardLauncherV2", "launch", "reverted on-chain");

    let token: Address = ZERO_ADDRESS;
    let pool: Address = ZERO_ADDRESS;
    let seededToPool = 0n;
    let toCreator = 0n;
    for (const log of receipt.logs) {
      try {
        const decoded = decodeEventLog({ abi: StockRewardLauncherV2ABI, data: log.data, topics: log.topics });
        if (decoded.eventName === "Launched") {
          const args = decoded.args as { token: Address; pool: Address; seededToPool: bigint; toCreator: bigint };
          token = args.token;
          pool = args.pool;
          seededToPool = args.seededToPool;
          toCreator = args.toCreator;
          break;
        }
      } catch { /* not our event */ }
    }
    if (token === ZERO_ADDRESS && predictedToken) token = predictedToken;
    if (token === ZERO_ADDRESS) throw new ContractCallError("StockRewardLauncherV2", "launch", "Launched event not found in receipt");

    return { token, pool, seededToPool, toCreator, txResult: this.toTx(receipt) };
  }

  // ── Claim (Merkle distributor) ────────────────────────────────────────────

  /** Number of published reward epochs. */
  async getEpochCount(): Promise<bigint> {
    const a = this.requireDeployed("epochCount");
    return this.publicClient.readContract({
      address: a.distributor,
      abi: MerkleStockDistributorABI,
      functionName: "epochCount",
    });
  }

  /** Read a published epoch. */
  async getEpoch(epoch: bigint): Promise<StockEpoch> {
    const a = this.requireDeployed("epochs");
    const e = (await this.publicClient.readContract({
      address: a.distributor,
      abi: MerkleStockDistributorABI,
      functionName: "epochs",
      args: [epoch],
    })) as readonly [Address, Hash, bigint, bigint, number, number, boolean];
    return {
      epoch: Number(epoch),
      stock: e[0],
      root: e[1],
      totalAmount: e[2],
      claimedAmount: e[3],
      createdAt: Number(e[4]),
      claimDeadline: Number(e[5]),
      closed: e[6],
    };
  }

  /** Whether `account` has claimed its leaf for an epoch. */
  async hasClaimed(epoch: bigint, account: Address): Promise<boolean> {
    const a = this.requireDeployed("hasClaimed");
    return this.publicClient.readContract({
      address: a.distributor,
      abi: MerkleStockDistributorABI,
      functionName: "hasClaimed",
      args: [epoch, account],
    });
  }

  /** Amount still unclaimed for an epoch. */
  async getUnclaimed(epoch: bigint): Promise<bigint> {
    const a = this.requireDeployed("unclaimed");
    return this.publicClient.readContract({
      address: a.distributor,
      abi: MerkleStockDistributorABI,
      functionName: "unclaimed",
      args: [epoch],
    });
  }

  /**
   * Claim tokenized-stock rewards for an epoch. The Merkle `proof` is NOT computed on-chain — it
   * comes from the keeper's off-chain epoch state (the indexer / claim API); the caller supplies
   * it. Uses `claimFor` when `params.account` is set, otherwise `claim` for the wallet account.
   */
  async claim(params: StockClaimParams): Promise<TxResult> {
    const a = this.requireDeployed("claim");
    const account = this.requireWallet("stock.claim");
    if (!params.proof || params.proof.length === 0) {
      throw new ValidationError("proof", "a Merkle proof (from the keeper/indexer) is required to claim");
    }
    const hash = params.account
      ? await this.walletClient!.writeContract({
          address: a.distributor,
          abi: MerkleStockDistributorABI,
          functionName: "claimFor",
          args: [params.epoch, params.account, params.stock, params.amount, params.proof],
          account,
          chain: this.walletClient!.chain,
        })
      : await this.walletClient!.writeContract({
          address: a.distributor,
          abi: MerkleStockDistributorABI,
          functionName: "claim",
          args: [params.epoch, params.stock, params.amount, params.proof],
          account,
          chain: this.walletClient!.chain,
        });
    const receipt = await this.publicClient.waitForTransactionReceipt({ hash });
    if (receipt.status === "reverted") throw new ContractCallError("MerkleStockDistributor", "claim", "reverted on-chain");
    return this.toTx(receipt);
  }

  // ── internals ─────────────────────────────────────────────────────────────

  /** Read the live native/USD keeper price + fail closed on staleness. */
  private async readKeeperPrice(bondingCurve: Address): Promise<{ nativeUsdPrice: bigint }> {
    const [nativeUsdPrice, updatedAt, maxStale] = await Promise.all([
      this.publicClient.readContract({ address: bondingCurve, abi: StockKeeperABI, functionName: "keeperPriceUsd" }) as Promise<bigint>,
      this.publicClient.readContract({ address: bondingCurve, abi: StockKeeperABI, functionName: "keeperPriceUpdatedAt" }) as Promise<bigint>,
      this.publicClient.readContract({ address: bondingCurve, abi: StockKeeperABI, functionName: "maxPriceStale" }) as Promise<bigint>,
    ]);
    if (Math.floor(Date.now() / 1000) - Number(updatedAt) > Number(maxStale)) {
      throw new ContractCallError("BondingCurve", "keeperPriceUsd", "live price feed is stale right now — try again in a moment");
    }
    if (nativeUsdPrice <= 0n) throw new ContractCallError("BondingCurve", "keeperPriceUsd", "keeper price unset");
    return { nativeUsdPrice };
  }

  private toTx(receipt: { transactionHash: Hash; blockNumber: bigint; gasUsed: bigint }): TxResult {
    return { hash: receipt.transactionHash, blockNumber: receipt.blockNumber, gasUsed: receipt.gasUsed };
  }
}
