// RHLaunchpad — the public orchestrator for Robinhood's direct-to-v4 "quick launch" (memecoin
// fair launch). One `launch()` deploys the token, creates + configures the v4 pool (via the
// shared, permissionless LaunchHook), and seeds concentrated liquidity — no bonding curve.
// `devBuy()` is a standing entry point any caller can use once a pool's 3-minute sniper guard
// has elapsed. Read verbatim from the app's `src/lib/contracts.ts` RHLaunchpadABI.
export const RHLaunchpadABI = [
  {
    name: "launch",
    type: "function",
    stateMutability: "payable",
    inputs: [
      { name: "name", type: "string" },
      { name: "symbol", type: "string" },
      { name: "supply", type: "uint256" },
      { name: "liquidityTokenAmount", type: "uint256" },
      { name: "sqrtPriceX96", type: "uint160" },
      { name: "tickLower", type: "int24" },
      { name: "tickUpper", type: "int24" },
      { name: "liquidityDelta", type: "int256" },
    ],
    outputs: [
      { name: "token", type: "address" },
      { name: "poolId", type: "bytes32" },
    ],
  },
  {
    name: "devBuy",
    type: "function",
    stateMutability: "payable",
    inputs: [
      {
        name: "key",
        type: "tuple",
        components: [
          { name: "currency0", type: "address" },
          { name: "currency1", type: "address" },
          { name: "fee", type: "uint24" },
          { name: "tickSpacing", type: "int24" },
          { name: "hooks", type: "address" },
        ],
      },
      { name: "amountIn", type: "uint256" },
      { name: "sqrtPriceLimitX96", type: "uint160" },
      { name: "recipient", type: "address" },
    ],
    outputs: [{ name: "boughtAmount", type: "uint256" }],
  },
  {
    name: "launchHook",
    type: "function",
    stateMutability: "view",
    inputs: [],
    outputs: [{ name: "", type: "address" }],
  },
  // Live native-denominated launch fee (USD-pegged, derived from the BondingCurve's keeper
  // price). launch()'s msg.value must be >= this; any remainder is wrapped as pool-side WETH.
  {
    name: "effectiveLaunchFee",
    type: "function",
    stateMutability: "view",
    inputs: [],
    outputs: [{ name: "", type: "uint256" }],
  },
  {
    name: "TokenCreated",
    type: "event",
    inputs: [
      { name: "token", type: "address", indexed: true },
      { name: "creator", type: "address", indexed: true },
      { name: "name", type: "string", indexed: false },
      { name: "symbol", type: "string", indexed: false },
      { name: "initialSupply", type: "uint256", indexed: false },
    ],
  },
  {
    name: "DevBuyExecuted",
    type: "event",
    inputs: [
      { name: "token", type: "address", indexed: true },
      { name: "buyer", type: "address", indexed: true },
      { name: "wethIn", type: "uint256", indexed: false },
      { name: "tokenOut", type: "uint256", indexed: false },
    ],
  },
] as const;
