// launch-math.ts — USD-anchored, single-sided concentrated-liquidity seed math.
//
// Ported verbatim from the app (`src/lib/v3-launch-params.ts` + `src/lib/rh-launch-params.ts`)
// so the SDK computes the SAME ticks/sqrtPrice as the frontend and the Hardhat ops scripts.
// Two mechanisms share this file:
//
//   • computeV3FairLaunchParams — tick spacing is a function of the fee tier (v3: 100→1,
//     500→10, 3000→60, 10000→200). Used by HookOSV3Launcher (direct-to-v3) AND
//     StockRewardLauncherV4 (direct-to-v4, which inherited v3's concentrated-liquidity model).
//     Returns no `liquidityDelta` — those launchers derive it on-chain from the token amount.
//
//   • computeFairLaunchParams — a single protocol-wide tick spacing of 60. Used by the
//     RHLaunchpad direct-to-v4 memecoin path (quick launch). Returns a `liquidityDelta`.
//
// 100% of supply is deposited single-sided (all token, zero WETH) with the pool's initial
// price set EXACTLY at the boundary tick of the range, so no WETH is needed to seed it and
// there is ZERO creator pre-allocation. Real buys move price INTO the range and the position
// naturally converts token liquidity into WETH liquidity — standard Uniswap v3/v4 behavior.
import { parseEther } from "viem";
import type { FairLaunchParams, V3FairLaunchParams } from "./types.js";
import { ValidationError } from "./errors.js";

// ── v3 fee-tier → tick spacing ───────────────────────────────────────────────

/** Canonical Uniswap v3 fee tiers → tickSpacing (also the v4 tiers the stock launcher uses). */
export const V3_TICK_SPACING: Record<number, number> = {
  100: 1,
  500: 10,
  3000: 60,
  10000: 200,
};

/** Fee tiers a creator can pick in the launch UI (bps of the fee, e.g. 10000 = 1%). */
export const V3_FEE_TIERS = [500, 3000, 10000] as const;
export type V3FeeTier = (typeof V3_FEE_TIERS)[number];

/** Default: the 1% tier — the memecoin-standard tier and the one the buyback carve is sized for. */
export const V3_DEFAULT_FEE_TIER: V3FeeTier = 10000;

export function tickSpacingForFee(feeTier: number): number {
  const spacing = V3_TICK_SPACING[feeTier];
  if (!spacing) throw new ValidationError("feeTier", `Unsupported v3 fee tier: ${feeTier}`);
  return spacing;
}

/** RHLaunchpad's single protocol-wide tick spacing (direct-to-v4 memecoin path). */
export const RH_TICK_SPACING = 60;

// ── v3/v4 TickMath sqrt-ratio bounds (no-limit sentinels for swaps) ──────────
export const MIN_SQRT_RATIO = 4295128739n + 1n;
export const MAX_SQRT_RATIO = 1461446703485210103287273052203988822378723970342n - 1n;
/** Aliases kept for the v3-launch naming used across the app. */
export const V3_MIN_SQRT_RATIO = MIN_SQRT_RATIO;
export const V3_MAX_SQRT_RATIO = MAX_SQRT_RATIO;

// ── internal helpers ─────────────────────────────────────────────────────────

function isqrt(n: bigint): bigint {
  if (n < 0n) throw new Error("negative");
  if (n < 2n) return n;
  let x = n, y = (x + 1n) / 2n;
  while (y < x) { x = y; y = (x + n / x) / 2n; }
  return x;
}

/** Tick delta (spacing-aligned) needed to move a raw price RATIO by `mult` (e.g. 25 = 25x). */
function tickForPriceMultiplier(mult: number, spacing: number): number {
  const raw = Math.log(mult) / Math.log(1.0001);
  const aligned = Math.round(raw / spacing) * spacing;
  // A zero-width range is invalid — always give the position at least one tick of room.
  return aligned === 0 ? spacing : aligned;
}

// ── computeV3FairLaunchParams (fee-tier-aware; HookOSV3Launcher + StockRewardLauncherV4) ──

/**
 * Compute a USD-anchored seed price + a SINGLE-SIDED concentrated range holding the ENTIRE
 * supply, for a fee-tier-aware v3/v4 launcher. Returns no `liquidityDelta` — those launchers
 * seed `totalSupply` on-chain and derive liquidity from it.
 *
 * @param targetMcapUsd  Target opening market cap in USD (whole dollars).
 * @param supplyTokens   FULL token supply (plain count, not wei) — ALL of it seeds the pool.
 * @param nativeUsdPrice Fresh native/USD price, 1e18-scaled (BondingCurve.keeperPriceUsd()).
 * @param tokenIsZero    Whether the (predicted) token address sorts below WETH.
 * @param feeTier        v3/v4 fee tier (100/500/3000/10000) — drives tickSpacing alignment.
 * @param bandWidthMultiplier How far price can rise from the seed before the position runs
 *                            out of room (default 25 = 25x).
 */
export function computeV3FairLaunchParams(opts: {
  targetMcapUsd: bigint;
  supplyTokens: bigint;
  nativeUsdPrice: bigint;
  tokenIsZero: boolean;
  feeTier?: number;
  bandWidthMultiplier?: number;
}): V3FairLaunchParams {
  const {
    targetMcapUsd,
    supplyTokens,
    nativeUsdPrice,
    tokenIsZero,
    feeTier = V3_DEFAULT_FEE_TIER,
    bandWidthMultiplier = 25,
  } = opts;

  if (bandWidthMultiplier <= 1) throw new ValidationError("bandWidthMultiplier", "must be > 1");
  if (supplyTokens <= 0n) throw new ValidationError("supplyTokens", "must be > 0");
  if (targetMcapUsd <= 0n) throw new ValidationError("targetMcapUsd", "must be > 0");
  if (nativeUsdPrice <= 0n) throw new ValidationError("nativeUsdPrice", "must be > 0 (stale or unset keeper price)");

  const spacing = tickSpacingForFee(feeTier);

  const pricePerTokenUsd1e18 = (targetMcapUsd * 10n ** 18n) / supplyTokens;
  if (pricePerTokenUsd1e18 <= 0n) throw new ValidationError("targetMcapUsd", "target MCap too low for this supply");
  const num = tokenIsZero ? pricePerTokenUsd1e18 : nativeUsdPrice;
  const den = tokenIsZero ? nativeUsdPrice : pricePerTokenUsd1e18;
  const seedSqrtPriceX96 = isqrt((num * (2n ** 192n)) / den);
  const seedSqrtP = Number(seedSqrtPriceX96) / Number(2n ** 96n);
  const priceRatioRaw = seedSqrtP * seedSqrtP;
  const seedTick = Math.round((Math.log(priceRatioRaw) / Math.log(1.0001)) / spacing) * spacing;

  // Single-sided: the range extends AWAY from the seed price in only one direction —
  // upward (tokenIsZero) or downward (!tokenIsZero) — never both.
  const offset = tickForPriceMultiplier(bandWidthMultiplier, spacing);
  const tickLower = tokenIsZero ? seedTick : seedTick - offset;
  const tickUpper = tokenIsZero ? seedTick + offset : seedTick;

  // sqrtPriceX96 derives from the SAME boundary tick as the range (never an independently
  // computed price), biased 2 wei "outside the range" so the on-chain price never resolves
  // to a tick strictly inside it (which would require a nonzero WETH amount msg.value can't
  // supply).
  const boundaryTick = tokenIsZero ? tickLower : tickUpper;
  const rawSqrt = Math.pow(1.0001, boundaryTick / 2) * Math.pow(2, 96);
  const sqrtPriceX96 = tokenIsZero ? BigInt(Math.floor(rawSqrt)) - 2n : BigInt(Math.ceil(rawSqrt)) + 2n;

  const nativeUsdFloat = Number(nativeUsdPrice) / 1e18;
  const supplyFloat = Number(supplyTokens);
  const seedRatio = Math.pow(1.0001, seedTick);
  const derivedMcapUsd = (tokenIsZero ? seedRatio : 1 / seedRatio) * nativeUsdFloat * supplyFloat;

  return { sqrtPriceX96, tickLower, tickUpper, feeTier, tickSpacing: spacing, seedTick, derivedMcapUsd };
}

// ── computeFairLaunchParams (spacing 60; RHLaunchpad direct-to-v4 quick launch) ──

/**
 * Compute a USD-anchored seed price + a SINGLE-SIDED position covering the ENTIRE supply for
 * a RHLaunchpad direct-to-v4 fair launch. Returns a `liquidityDelta` (RHLaunchpad's `launch()`
 * takes it explicitly, unlike the v3 launchers).
 *
 * @param targetMcapUsd       Target opening market cap in USD.
 * @param supplyTokens        FULL token supply (plain count, not wei) — ALL of it seeds the pool.
 * @param nativeUsdPrice      Fresh native/USD price, 1e18-scaled (BondingCurve.keeperPriceUsd()).
 * @param tokenIsZero         Whether the (predicted) token address sorts below WETH.
 * @param bandWidthMultiplier How far the range extends from the seed price (default 25 = 25x).
 */
export function computeFairLaunchParams(opts: {
  targetMcapUsd: bigint;
  supplyTokens: bigint;
  nativeUsdPrice: bigint;
  tokenIsZero: boolean;
  bandWidthMultiplier?: number;
}): FairLaunchParams {
  const { targetMcapUsd, supplyTokens, nativeUsdPrice, tokenIsZero, bandWidthMultiplier = 25 } = opts;

  if (bandWidthMultiplier <= 1) throw new ValidationError("bandWidthMultiplier", "must be > 1");
  if (supplyTokens <= 0n) throw new ValidationError("supplyTokens", "must be > 0");
  if (nativeUsdPrice <= 0n) throw new ValidationError("nativeUsdPrice", "must be > 0 (stale or unset keeper price)");

  const pricePerTokenUsd1e18 = (targetMcapUsd * 10n ** 18n) / supplyTokens;
  const num = tokenIsZero ? pricePerTokenUsd1e18 : nativeUsdPrice;
  const den = tokenIsZero ? nativeUsdPrice : pricePerTokenUsd1e18;
  const seedSqrtPriceX96 = isqrt((num * (2n ** 192n)) / den);
  const seedSqrtP = Number(seedSqrtPriceX96) / Number(2n ** 96n);
  const priceRatioRaw = seedSqrtP * seedSqrtP;
  const seedTick = Math.round((Math.log(priceRatioRaw) / Math.log(1.0001)) / RH_TICK_SPACING) * RH_TICK_SPACING;

  const offset = Math.round((Math.log(bandWidthMultiplier) / Math.log(1.0001)) / RH_TICK_SPACING) * RH_TICK_SPACING;
  const tickLower = tokenIsZero ? seedTick : seedTick - offset;
  const tickUpper = tokenIsZero ? seedTick + offset : seedTick;

  const boundaryTick = tokenIsZero ? tickLower : tickUpper;
  const rawSqrt = Math.pow(1.0001, boundaryTick / 2) * Math.pow(2, 96);
  const sqrtPriceX96 = tokenIsZero ? BigInt(Math.floor(rawSqrt)) - 2n : BigInt(Math.ceil(rawSqrt)) + 2n;

  const sqrtA = Math.pow(1.0001, tickLower / 2);
  const sqrtB = Math.pow(1.0001, tickUpper / 2);

  // Full supply == the single-sided token amount at this boundary:
  //   tokenIsZero:  amount0 = L*(1/sqrtA - 1/sqrtB) = supply -> L = supply / (1/sqrtA - 1/sqrtB)
  //   !tokenIsZero: amount1 = L*(sqrtB - sqrtA)      = supply -> L = supply / (sqrtB - sqrtA)
  const supplyFloat = Number(supplyTokens);
  const L = tokenIsZero
    ? supplyFloat / (1 / sqrtA - 1 / sqrtB)
    : supplyFloat / (sqrtB - sqrtA);

  if (!(L > 0) || !isFinite(L)) throw new ValidationError("liquidityDelta", `computed non-positive/invalid liquidityDelta (L=${L})`);

  const nativeUsdFloat = Number(nativeUsdPrice) / 1e18;
  const derivedMcapUsd = (tokenIsZero ? seedSqrtP * seedSqrtP : 1 / (seedSqrtP * seedSqrtP)) * nativeUsdFloat * supplyFloat;

  return {
    sqrtPriceX96,
    tickLower,
    tickUpper,
    liquidityDelta: parseEther(L.toFixed(18)),
    seedTick,
    derivedMcapUsd,
  };
}
