// StockRewardVault — holds the tax skimmed from stock-reward trades (in WETH via the V4 hook, or
// USDG-settled on V2), buys the creator's chosen tokenized stocks, and funds epoch payouts. This
// is the read surface used by dashboards + the SDK: the reward allowlist, the creator's basket, and
// holder-pool telemetry. Read verbatim from the app's dapp-templates.ts instanceAbi + stock-launch.ts.
export const StockRewardVaultABI = [
  // The creator's chosen reward basket (weights in bps, MUST sum to 10000).
  {
    name: "getBasket",
    type: "function",
    stateMutability: "view",
    inputs: [{ name: "rewardToken", type: "address" }],
    outputs: [
      {
        name: "",
        type: "tuple[]",
        components: [
          { name: "stock", type: "address" },
          { name: "weightBps", type: "uint16" },
        ],
      },
    ],
  },
  // The on-chain reward allowlist — only allowlisted stocks can be bought for holders.
  {
    name: "stockAllowed",
    type: "function",
    stateMutability: "view",
    inputs: [{ name: "stock", type: "address" }],
    outputs: [{ name: "", type: "bool" }],
  },
  // The Chainlink-shaped USD feed bound to a stock (8dp).
  {
    name: "priceFeed",
    type: "function",
    stateMutability: "view",
    inputs: [{ name: "stock", type: "address" }],
    outputs: [{ name: "", type: "address" }],
  },
  // Holder-pool telemetry.
  {
    name: "holderUsdgPool",
    type: "function",
    stateMutability: "view",
    inputs: [{ name: "rewardToken", type: "address" }],
    outputs: [{ name: "", type: "uint256" }],
  },
  {
    name: "totalHolderUsdg",
    type: "function",
    stateMutability: "view",
    inputs: [],
    outputs: [{ name: "", type: "uint256" }],
  },
  {
    name: "totalStockBought",
    type: "function",
    stateMutability: "view",
    inputs: [{ name: "stock", type: "address" }],
    outputs: [{ name: "", type: "uint256" }],
  },
  // The oracle-floored USDG amount a given asset (e.g. WETH) is worth — the min-out floor the
  // vault prices its Uniswap-V3 conversions against. Fails CLOSED (0) on a stale/bad feed.
  {
    name: "usdgFloorForAsset",
    type: "function",
    stateMutability: "view",
    inputs: [
      { name: "asset", type: "address" },
      { name: "amountIn", type: "uint256" },
    ],
    outputs: [{ name: "floor", type: "uint256" }],
  },
] as const;

// WethUsdAggregatorAdapter — the Chainlink-shaped (AggregatorV3Interface) WETH/USD adapter the V4
// stock suite reads. Wraps the BondingCurve keeper price and fails CLOSED (all-zeros) on stale/bad
// price. `answer` is 1e8-scaled (decimals() == 8). This is the WETH/USD floor the vault prices
// stock buys against. Read verbatim from contracts/contracts/stock/WethUsdAggregatorAdapter.sol.
export const WethUsdAggregatorABI = [
  {
    name: "latestRoundData",
    type: "function",
    stateMutability: "view",
    inputs: [],
    outputs: [
      { name: "roundId", type: "uint80" },
      { name: "answer", type: "int256" },
      { name: "startedAt", type: "uint256" },
      { name: "updatedAt", type: "uint256" },
      { name: "answeredInRound", type: "uint80" },
    ],
  },
  { name: "decimals", type: "function", stateMutability: "view", inputs: [], outputs: [{ name: "", type: "uint8" }] },
  { name: "description", type: "function", stateMutability: "view", inputs: [], outputs: [{ name: "", type: "string" }] },
] as const;
