// MerkleStockDistributor — pays out the tokenized stock rewards to holders per epoch, gated by a
// Merkle proof. The keeper publishes an epoch (stock + merkle root + total amount) off-chain and
// holders claim their leaf with a proof supplied by the keeper/indexer (the SDK never fabricates a
// proof — the caller passes it in). Read verbatim from the app's dapp-templates.ts instanceAbi.
export const MerkleStockDistributorABI = [
  // ── Reads ──
  { name: "epochCount", type: "function", stateMutability: "view", inputs: [], outputs: [{ name: "", type: "uint256" }] },
  {
    name: "epochs",
    type: "function",
    stateMutability: "view",
    inputs: [{ name: "epoch", type: "uint256" }],
    outputs: [
      { name: "stock", type: "address" },
      { name: "root", type: "bytes32" },
      { name: "totalAmount", type: "uint256" },
      { name: "claimedAmount", type: "uint256" },
      { name: "createdAt", type: "uint40" },
      { name: "claimDeadline", type: "uint40" },
      { name: "closed", type: "bool" },
    ],
  },
  {
    name: "hasClaimed",
    type: "function",
    stateMutability: "view",
    inputs: [
      { name: "epoch", type: "uint256" },
      { name: "account", type: "address" },
    ],
    outputs: [{ name: "", type: "bool" }],
  },
  {
    name: "unclaimed",
    type: "function",
    stateMutability: "view",
    inputs: [{ name: "epoch", type: "uint256" }],
    outputs: [{ name: "", type: "uint256" }],
  },
  // ── Writes (Merkle-proof gated; proof comes from the keeper/indexer) ──
  {
    name: "claim",
    type: "function",
    stateMutability: "nonpayable",
    inputs: [
      { name: "epoch", type: "uint256" },
      { name: "stock", type: "address" },
      { name: "amount", type: "uint256" },
      { name: "proof", type: "bytes32[]" },
    ],
    outputs: [],
  },
  {
    name: "claimFor",
    type: "function",
    stateMutability: "nonpayable",
    inputs: [
      { name: "epoch", type: "uint256" },
      { name: "account", type: "address" },
      { name: "stock", type: "address" },
      { name: "amount", type: "uint256" },
      { name: "proof", type: "bytes32[]" },
    ],
    outputs: [],
  },
  {
    name: "claimForMany",
    type: "function",
    stateMutability: "nonpayable",
    inputs: [
      { name: "epochIds", type: "uint256[]" },
      { name: "accounts", type: "address[]" },
      { name: "stocks", type: "address[]" },
      { name: "amounts", type: "uint256[]" },
      { name: "proofs", type: "bytes32[][]" },
    ],
    outputs: [{ name: "", type: "uint256" }],
  },
] as const;
