// StockRewardLauncherV4 — the WETH-paired, HOOK-TAXED, direct-to-Uniswap-v4 stock-reward
// launcher (Robinhood 4663). The token is a CLEAN, untaxed ERC-20; the 2–5% buy/sell tax is
// charged INSIDE the swap by StockTaxHook (a v4 beforeSwap/afterSwap hook), collected in WETH,
// and split creator 0.5% / platform 0.5% / StockRewardVault remainder — so sells are never
// honeypotted. ONE atomic `launch(LaunchParams)`: deploy token → build the v4 PoolKey with
// StockTaxHook → initialize (front-run guard) → register for taxation + optional sniper guard →
// single-sided seed 100% of the float (LP NFT to 0xdEaD) → optional min-out-guarded dev buy →
// hand creatorAmount to the creator → emit Launched. Read verbatim from the app's stock-launch.ts.
export const StockRewardLauncherV4ABI = [
  {
    name: "launch",
    type: "function",
    stateMutability: "payable", // payable for the OPTIONAL atomic dev buy (msg.value === initialBuyEth)
    inputs: [
      {
        name: "p",
        type: "tuple",
        components: [
          { name: "name", type: "string" },
          { name: "symbol", type: "string" },
          { name: "supply", type: "uint256" }, // full 18-dec supply; (supply − creatorAmount) is seeded
          { name: "creatorAmount", type: "uint256" }, // 0 for a pure fair launch
          { name: "sqrtPriceX96", type: "uint160" }, // single-sided seed price (computed off-chain for the sort)
          { name: "tickLower", type: "int24" },
          { name: "tickUpper", type: "int24" },
          { name: "fee", type: "uint24" }, // v4 pool fee tier
          { name: "tickSpacing", type: "int24" }, // v4 pool tick spacing
          { name: "admin", type: "address" }, // final DEFAULT_ADMIN of the token (rescue authority)
          { name: "creator", type: "address" }, // pool creator (hook tax authority) + creatorAmount recipient
          { name: "buyBps", type: "uint16" },
          { name: "sellBps", type: "uint16" },
          { name: "guardWindowSecs", type: "uint256" }, // sniper-guard window (0 = none; ≤ 1h on-chain)
          { name: "initialBuyEth", type: "uint256" }, // optional dev buy, funded from msg.value (0 = none)
          { name: "initialBuyMinOut", type: "uint256" }, // REQUIRED > 0 when initialBuyEth > 0 (never 0-slippage)
          { name: "initialBuyLimitSqrtPriceX96", type: "uint160" }, // coarse swap price limit for the dev buy
        ],
      },
    ],
    outputs: [
      { name: "token", type: "address" },
      { name: "poolId", type: "bytes32" },
      { name: "positionId", type: "uint256" },
    ],
  },
  {
    // Enumerate launches by index (0..launchCount-1) — the same walk the keeper uses to
    // auto-discover launched stock-reward tokens (RH public RPC times out on eth_getLogs).
    name: "getLaunch",
    type: "function",
    stateMutability: "view",
    inputs: [{ name: "id", type: "uint256" }],
    outputs: [
      {
        name: "",
        type: "tuple",
        components: [
          { name: "token", type: "address" },
          { name: "poolId", type: "bytes32" },
          { name: "creator", type: "address" },
          { name: "positionId", type: "uint256" },
          { name: "fee", type: "uint24" },
          { name: "seededToPool", type: "uint256" },
          { name: "toCreator", type: "uint256" },
          { name: "createdAt", type: "uint256" },
        ],
      },
    ],
  },
  {
    // On-chain identity fallback for the token page — a stock-reward token is minted by this
    // launcher (NOT TokenFactory), so getLaunchByToken resolves identity straight from chain.
    name: "getLaunchByToken",
    type: "function",
    stateMutability: "view",
    inputs: [{ name: "token", type: "address" }],
    outputs: [
      {
        name: "",
        type: "tuple",
        components: [
          { name: "token", type: "address" },
          { name: "poolId", type: "bytes32" },
          { name: "creator", type: "address" },
          { name: "positionId", type: "uint256" },
          { name: "fee", type: "uint24" },
          { name: "seededToPool", type: "uint256" },
          { name: "toCreator", type: "uint256" },
          { name: "createdAt", type: "uint256" },
        ],
      },
    ],
  },
  // Canonical launch event — `poolId` is the v4 poolId (a v4 pool is not an address).
  {
    name: "Launched",
    type: "event",
    inputs: [
      { name: "token", type: "address", indexed: true },
      { name: "poolId", type: "bytes32", indexed: true },
      { name: "creator", type: "address", indexed: true },
      { name: "seededToPool", type: "uint256", indexed: false },
      { name: "toCreator", type: "uint256", indexed: false },
    ],
  },
  {
    name: "DevBuyExecuted",
    type: "event",
    inputs: [
      { name: "token", type: "address", indexed: true },
      { name: "creator", type: "address", indexed: true },
      { name: "ethIn", type: "uint256", indexed: false },
      { name: "tokenOut", type: "uint256", indexed: false },
    ],
  },
  // Read views present on V4.
  { name: "weth", type: "function", stateMutability: "view", inputs: [], outputs: [{ name: "", type: "address" }] },
  { name: "stockTaxHook", type: "function", stateMutability: "view", inputs: [], outputs: [{ name: "", type: "address" }] },
  { name: "launchCount", type: "function", stateMutability: "view", inputs: [], outputs: [{ name: "", type: "uint256" }] },
  { name: "isStockRewardToken", type: "function", stateMutability: "view", inputs: [{ name: "token", type: "address" }], outputs: [{ name: "", type: "bool" }] },
] as const;
