import {
  type PublicClient,
  type WalletClient,
  type Address,
  type Hash,
  getContractAddress,
  decodeEventLog,
  parseEther,
} from "viem";
import { RHLaunchpadABI } from "../abis/RHLaunchpad.js";
import { StockKeeperABI } from "../abis/StockRewardLauncherV2.js";
import type { QuickLaunchAddresses } from "../addresses.js";
import { WalletRequiredError, ContractCallError, ValidationError } from "../errors.js";
import {
  computeFairLaunchParams,
  RH_TICK_SPACING,
  MIN_SQRT_RATIO,
  MAX_SQRT_RATIO,
} from "../launch-math.js";
import type {
  QuickLaunchOptions,
  QuickLaunchResult,
  QuickLaunchBuildResult,
  DevBuyResult,
  TxResult,
} from "../types.js";

const ZERO_ADDRESS: Address = "0x0000000000000000000000000000000000000000";
const isDeployed = (a: Address | undefined | null): boolean => !!a && a !== ZERO_ADDRESS;

/** Default opening market cap (USD) for a quick launch — mirrors the app's V3_TARGET_MCAP_USD. */
export const QUICK_LAUNCH_TARGET_MCAP_USD = 5500n;

/** The v4 pool fee tier + tick spacing every RHLaunchpad pool uses. */
export const QUICK_LAUNCH_FEE_TIER = 3000;
export const QUICK_LAUNCH_TICK_SPACING = RH_TICK_SPACING; // 60

/**
 * QuickLaunchModule — the RHLaunchpad direct-to-v4 "quick launch" memecoin fast path
 * (Robinhood Chain 4663 only).
 *
 * On Robinhood, "Quick Launch" IS the direct-to-DEX fair-launch mechanism: one `launch()` call
 * deploys the token, creates the v4 pool (via the shared, permissionless LaunchHook), and seeds
 * CONCENTRATED liquidity holding 100% of supply single-sided (zero creator pre-allocation, no
 * bonding curve). A USD-anchored seed price is read live from the same keeper feed the curve uses
 * for fees/graduation. `devBuy` is a standing entry point any caller can use once a pool's
 * 3-minute sniper guard has elapsed.
 *
 * Robinhood-only: every method throws a clear error on chains where RHLaunchpad isn't deployed.
 * Instantiate the client with `chainId: 4663`.
 *
 * @example
 * ```ts
 * const hookos = new HookOS({ chainId: 4663, walletClient });
 *
 * const fee = await hookos.quickLaunch.getEffectiveLaunchFee();
 * const res = await hookos.quickLaunch.launch({
 *   name: "Pepe", symbol: "PEPE", supplyTokens: 1_000_000_000n,
 * });
 * ```
 */
export class QuickLaunchModule {
  constructor(
    private readonly addresses: QuickLaunchAddresses | null,
    private readonly chainId: number,
    private readonly publicClient: PublicClient,
    private readonly walletClient?: WalletClient,
  ) {}

  /** Whether RHLaunchpad quick launch is deployed on the client's chain. */
  get available(): boolean {
    return !!this.addresses && isDeployed(this.addresses.launchpad);
  }

  /** The RHLaunchpad address this module targets (zero if not deployed on this chain). */
  get launchpadAddress(): Address {
    return this.addresses?.launchpad ?? ZERO_ADDRESS;
  }

  private requireDeployed(op: string): QuickLaunchAddresses {
    if (!this.addresses || !isDeployed(this.addresses.launchpad)) {
      throw new ContractCallError(
        "RHLaunchpad",
        op,
        `quick launch (RHLaunchpad) is Robinhood-only (chain 4663) — not deployed on chain ${this.chainId}`,
      );
    }
    return this.addresses;
  }

  private requireWallet(op: string) {
    if (!this.walletClient) throw new WalletRequiredError(op);
    const account = this.walletClient.account;
    if (!account) throw new WalletRequiredError(`${op} (no account)`);
    return account;
  }

  // ── Reads ─────────────────────────────────────────────────────────────────

  /** Live native-denominated launch fee (wei), USD-pegged at the keeper price. `launch()` sends this. */
  async getEffectiveLaunchFee(): Promise<bigint> {
    const a = this.requireDeployed("effectiveLaunchFee");
    return this.publicClient.readContract({
      address: a.launchpad,
      abi: RHLaunchpadABI,
      functionName: "effectiveLaunchFee",
    });
  }

  /** The shared LaunchHook attached to every RHLaunchpad pool. */
  async getLaunchHook(): Promise<Address> {
    const a = this.requireDeployed("launchHook");
    return this.publicClient.readContract({
      address: a.launchpad,
      abi: RHLaunchpadABI,
      functionName: "launchHook",
    });
  }

  // ── Build (compute launch args without sending) ────────────────────────────

  /**
   * Compute the ready-to-send RHLaunchpad `launch()` args (weth read + token prediction + live
   * keeper price + single-sided seed geometry + USD-pegged launch fee) WITHOUT sending.
   */
  async buildLaunchParams(opts: QuickLaunchOptions): Promise<QuickLaunchBuildResult> {
    const a = this.requireDeployed("buildLaunchParams");
    const targetMcapUsd = opts.targetMcapUsd ?? QUICK_LAUNCH_TARGET_MCAP_USD;

    // RHLaunchpad deploys the token at its own next CREATE nonce.
    const nonce = await this.publicClient.getTransactionCount({ address: a.launchpad });
    const predictedToken = getContractAddress({ from: a.launchpad, nonce: BigInt(nonce) });
    const tokenIsZero = predictedToken.toLowerCase() < a.weth.toLowerCase();

    const nativeUsdPrice = await this.readKeeperPrice(a.bondingCurve);

    const params = computeFairLaunchParams({
      targetMcapUsd,
      supplyTokens: opts.supplyTokens,
      nativeUsdPrice,
      tokenIsZero,
    });

    const launchFee = (await this.publicClient.readContract({
      address: a.launchpad,
      abi: RHLaunchpadABI,
      functionName: "effectiveLaunchFee",
    })) as bigint;

    return { predictedToken, tokenIsZero, launchFee, params };
  }

  // ── Launch (write) ─────────────────────────────────────────────────────────

  /**
   * Deploy a token and single-sided-seed 100% of its supply into a fresh v4 pool. `msg.value`
   * covers the live USD-pegged launch fee (no WETH needed to seed a single-sided position).
   * Requires a wallet client. Returns the launched token (decoded from `TokenCreated`).
   */
  async launch(opts: QuickLaunchOptions): Promise<QuickLaunchResult> {
    const a = this.requireDeployed("launch");
    const account = this.requireWallet("quickLaunch.launch");
    if (opts.supplyTokens <= 0n) throw new ValidationError("supplyTokens", "must be > 0");

    const built = await this.buildLaunchParams(opts);
    const supplyWei = opts.supplyTokens * 10n ** 18n;

    const hash = await this.walletClient!.writeContract({
      address: a.launchpad,
      abi: RHLaunchpadABI,
      functionName: "launch",
      args: [
        opts.name,
        opts.symbol.toUpperCase(),
        supplyWei,
        supplyWei, // fair launch: the FULL supply is the liquidityTokenAmount
        built.params.sqrtPriceX96,
        built.params.tickLower,
        built.params.tickUpper,
        built.params.liquidityDelta,
      ],
      value: built.launchFee,
      account,
      chain: this.walletClient!.chain,
    });

    const receipt = await this.publicClient.waitForTransactionReceipt({ hash });
    if (receipt.status === "reverted") throw new ContractCallError("RHLaunchpad", "launch", "reverted on-chain");

    let token: Address = ZERO_ADDRESS;
    for (const log of receipt.logs) {
      try {
        const decoded = decodeEventLog({ abi: RHLaunchpadABI, data: log.data, topics: log.topics });
        if (decoded.eventName === "TokenCreated") {
          token = (decoded.args as { token: Address }).token;
          break;
        }
      } catch { /* not our event */ }
    }
    // Deterministic CREATE address fallback (the contract deploys at exactly this nonce).
    if (token === ZERO_ADDRESS) token = built.predictedToken;

    return { token, derivedMcapUsd: built.params.derivedMcapUsd, txResult: this.toTx(receipt) };
  }

  /**
   * Buy into any LaunchHook pool once its 3-minute sniper guard has elapsed. The UI owns the
   * countdown; this just sends the swap (WETH-in). Requires a wallet client.
   */
  async devBuy(opts: { token: Address; amountInEther: number; recipient?: Address }): Promise<DevBuyResult> {
    const a = this.requireDeployed("devBuy");
    const account = this.requireWallet("quickLaunch.devBuy");

    const hookAddr = (await this.publicClient.readContract({
      address: a.launchpad,
      abi: RHLaunchpadABI,
      functionName: "launchHook",
    })) as Address;
    const tokenIsZero = opts.token.toLowerCase() < a.weth.toLowerCase();
    const key = tokenIsZero
      ? { currency0: opts.token, currency1: a.weth, fee: QUICK_LAUNCH_FEE_TIER, tickSpacing: QUICK_LAUNCH_TICK_SPACING, hooks: hookAddr }
      : { currency0: a.weth, currency1: opts.token, fee: QUICK_LAUNCH_FEE_TIER, tickSpacing: QUICK_LAUNCH_TICK_SPACING, hooks: hookAddr };
    const amountIn = parseEther(opts.amountInEther.toString());

    const hash = await this.walletClient!.writeContract({
      address: a.launchpad,
      abi: RHLaunchpadABI,
      functionName: "devBuy",
      args: [key, amountIn, tokenIsZero ? MAX_SQRT_RATIO : MIN_SQRT_RATIO, opts.recipient ?? account.address],
      value: amountIn,
      account,
      chain: this.walletClient!.chain,
    });

    const receipt = await this.publicClient.waitForTransactionReceipt({ hash });
    if (receipt.status === "reverted") throw new ContractCallError("RHLaunchpad", "devBuy", "reverted on-chain");

    let boughtAmount = 0n;
    for (const log of receipt.logs) {
      try {
        const decoded = decodeEventLog({ abi: RHLaunchpadABI, data: log.data, topics: log.topics });
        if (decoded.eventName === "DevBuyExecuted") {
          boughtAmount = (decoded.args as { tokenOut: bigint }).tokenOut;
          break;
        }
      } catch { /* not our event */ }
    }
    return { txResult: this.toTx(receipt), boughtAmount };
  }

  // ── internals ─────────────────────────────────────────────────────────────

  private async readKeeperPrice(bondingCurve: Address): Promise<bigint> {
    const [nativeUsdPrice, updatedAt, maxStale] = await Promise.all([
      this.publicClient.readContract({ address: bondingCurve, abi: StockKeeperABI, functionName: "keeperPriceUsd" }) as Promise<bigint>,
      this.publicClient.readContract({ address: bondingCurve, abi: StockKeeperABI, functionName: "keeperPriceUpdatedAt" }) as Promise<bigint>,
      this.publicClient.readContract({ address: bondingCurve, abi: StockKeeperABI, functionName: "maxPriceStale" }) as Promise<bigint>,
    ]);
    if (Math.floor(Date.now() / 1000) - Number(updatedAt) > Number(maxStale)) {
      throw new ContractCallError("BondingCurve", "keeperPriceUsd", "live price feed is stale right now — try again in a moment");
    }
    if (nativeUsdPrice <= 0n) throw new ContractCallError("BondingCurve", "keeperPriceUsd", "keeper price unset");
    return nativeUsdPrice;
  }

  private toTx(receipt: { transactionHash: Hash; blockNumber: bigint; gasUsed: bigint }): TxResult {
    return { hash: receipt.transactionHash, blockNumber: receipt.blockNumber, gasUsed: receipt.gasUsed };
  }
}
