// StockRewardLauncherV2 — the POOL-CREATING (legacy) stock-reward launcher (Robinhood 4663).
// A real launch creates a real Uniswap-v3 pool, single-sided-seeds 100% of the launch float, and
// a real buy skims exactly the configured token-level transfer tax. Superseded by V4 (which fixes
// the v3 exact-input taxed-sell revert by charging the tax inside a v4 hook in WETH) but kept
// available as a legacy path. Read verbatim from the app's stock-launch.ts.
export const StockRewardLauncherV2ABI = [
  {
    name: "launch",
    type: "function",
    stateMutability: "payable", // payable for the OPTIONAL atomic dev buy (msg.value = initialBuyEth [+ excess])
    inputs: [
      {
        name: "p",
        type: "tuple",
        components: [
          { name: "name", type: "string" },
          { name: "symbol", type: "string" },
          { name: "supply", type: "uint256" }, // full 18-dec supply; (supply − creatorAmount) is seeded
          { name: "creatorAmount", type: "uint256" }, // 0 for a pure fair launch
          { name: "tickLower", type: "int24" },
          { name: "tickUpper", type: "int24" },
          { name: "admin", type: "address" }, // final DEFAULT_ADMIN of the token
          { name: "creator", type: "address" }, // final tax authority + creatorAmount recipient
          { name: "vault", type: "address" }, // StockRewardVault — the tax skim sink
          { name: "buyBps", type: "uint16" },
          { name: "sellBps", type: "uint16" },
          { name: "dex", type: "uint8" }, // 0 = UniswapV3, 1 = HookSwap
          { name: "initialBuyEth", type: "uint256" }, // optional dev buy, funded from msg.value (0 = none)
          { name: "initialBuyMinOut", type: "uint256" }, // REQUIRED > 0 when initialBuyEth > 0 (never 0-slippage)
          { name: "initialBuyDeadline", type: "uint256" }, // 0 => block.timestamp
        ],
      },
    ],
    outputs: [
      { name: "token", type: "address" },
      { name: "pool", type: "address" },
      { name: "tokenId", type: "uint256" },
    ],
  },
  {
    name: "swapRouterOf",
    type: "function",
    stateMutability: "view",
    inputs: [{ name: "dex", type: "uint8" }],
    outputs: [{ name: "", type: "address" }],
  },
  {
    name: "getLaunchByToken",
    type: "function",
    stateMutability: "view",
    inputs: [{ name: "token", type: "address" }],
    outputs: [
      {
        name: "",
        type: "tuple",
        components: [
          { name: "token", type: "address" },
          { name: "pool", type: "address" },
          { name: "creator", type: "address" },
          { name: "tokenId", type: "uint256" },
          { name: "feeTier", type: "uint24" },
          { name: "dex", type: "uint8" },
          { name: "seededToPool", type: "uint256" },
          { name: "toCreator", type: "uint256" },
          { name: "createdAt", type: "uint256" },
        ],
      },
    ],
  },
  {
    name: "DevBuyExecuted",
    type: "event",
    inputs: [
      { name: "token", type: "address", indexed: true },
      { name: "creator", type: "address", indexed: true },
      { name: "ethIn", type: "uint256", indexed: false },
      { name: "minOut", type: "uint256", indexed: false },
    ],
  },
  {
    name: "Launched",
    type: "event",
    inputs: [
      { name: "token", type: "address", indexed: true },
      { name: "pool", type: "address", indexed: true },
      { name: "creator", type: "address", indexed: true },
      { name: "seededToPool", type: "uint256", indexed: false },
      { name: "toCreator", type: "uint256", indexed: false },
    ],
  },
  {
    name: "dexConfig",
    type: "function",
    stateMutability: "view",
    inputs: [{ name: "dex", type: "uint8" }],
    outputs: [
      { name: "factory", type: "address" },
      { name: "positionManager", type: "address" },
      { name: "feeTier", type: "uint24" },
      { name: "tickSpacing", type: "int24" },
    ],
  },
  { name: "weth", type: "function", stateMutability: "view", inputs: [], outputs: [{ name: "", type: "address" }] },
  { name: "launchCount", type: "function", stateMutability: "view", inputs: [], outputs: [{ name: "", type: "uint256" }] },
  { name: "isStockRewardToken", type: "function", stateMutability: "view", inputs: [{ name: "token", type: "address" }], outputs: [{ name: "", type: "bool" }] },
] as const;

/** Keeper price feed (native/USD) the stock pool is seeded against — read live off the chain's
 *  BondingCurve keeper (the same feed the Fair-V3 path uses). Fail-closed on staleness. */
export const StockKeeperABI = [
  { name: "keeperPriceUsd", type: "function", stateMutability: "view", inputs: [], outputs: [{ type: "uint256" }] },
  { name: "keeperPriceUpdatedAt", type: "function", stateMutability: "view", inputs: [], outputs: [{ type: "uint256" }] },
  { name: "maxPriceStale", type: "function", stateMutability: "view", inputs: [], outputs: [{ type: "uint256" }] },
] as const;
